package com.slayeritemreminders;

import com.google.gson.JsonParser;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class WikiTaskVariantBucketParserTest
{
	@Test
	public void parsesDeduplicatesAndExcludesAlternateGameModes()
	{
		String json = "{\"bucket\":["
			+ "{\"name\":\"Blue dragon\",\"page_name\":\"Blue dragon\"},"
			+ "{\"name\":\"Blue dragon\",\"page_name\":\"Blue dragon\"},"
			+ "{\"name\":\"Baby blue dragon\",\"page_name\":\"Baby blue dragon\"},"
			+ "{\"name\":\"Vorkath\",\"page_name\":\"Vorkath\"},"
			+ "{\"name\":\"Vorkath\",\"page_name\":\"Vorkath (PvM Arena)\"},"
			+ "{\"name\":\"Vorkath (Echo)\",\"page_name\":\"Vorkath (Echo)\"}]}";

		List<TaskVariant> variants = WikiTaskVariantBucketParser.parse(
			new JsonParser().parse(json).getAsJsonObject());

		assertEquals(3, variants.size());
		assertEquals("Blue dragon", variants.get(0).getWikiPage());
		assertEquals("Baby blue dragon", variants.get(1).getWikiPage());
		assertEquals("Vorkath", variants.get(2).getWikiPage());
	}
}

package com.slayeritemreminders;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import okhttp3.HttpUrl;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class WikiTaskVariantClientTest
{
	@Test
	public void fallsBackToMonsterBucketWhenTaskPagesDoNotExist()
	{
		WikiRequestManager manager = mock(WikiRequestManager.class);
		WikiRequestManager.RequestHandle handle = mock(WikiRequestManager.RequestHandle.class);
		List<HttpUrl.Builder> urls = new ArrayList<>();
		List<Consumer<JsonObject>> successes = new ArrayList<>();
		when(manager.request(any(HttpUrl.Builder.class), any(), any())).thenAnswer(invocation ->
		{
			urls.add(invocation.getArgument(0));
			successes.add(invocation.getArgument(1));
			return handle;
		});
		WikiTaskVariantClient client = new WikiTaskVariantClient(manager);
		AtomicReference<TaskVariantDiscoveryResult> result = new AtomicReference<>();

		client.lookup("Mystery", result::set);
		assertEquals("parse", urls.get(0).build().queryParameter("action"));
		successes.get(0).accept(missingPage());
		successes.get(1).accept(missingPage());

		assertEquals("bucket", urls.get(2).build().queryParameter("action"));
		String query = urls.get(2).build().queryParameter("query");
		assertEquals(true, query.contains("{'slayer_category','Mystery'}"));
		assertEquals(true, query.contains("{'slayer_category','Mysteries'}"));
		successes.get(2).accept(json("{\"bucket\":["
			+ "{\"name\":\"Mystery boss\",\"page_name\":\"Mystery boss\"}]}"));

		assertFalse(result.get().isUnavailable());
		assertEquals(1, result.get().getVariants().size());
		assertEquals("Mystery boss", result.get().getVariants().get(0).getWikiPage());
	}

	private static JsonObject missingPage()
	{
		return json("{\"error\":{\"code\":\"missingtitle\"}}");
	}

	private static JsonObject json(String value)
	{
		return new JsonParser().parse(value).getAsJsonObject();
	}
}

package com.slayeritemreminders;

import com.google.gson.JsonParser;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WikiRequiredItemResolverTest
{
	@Test
	public void buildsOneEscapedQueryForDistinctItemNames()
	{
		List<WikiRequiredItemRule> rules = Arrays.asList(
			new WikiRequiredItemRule("Basilisk", Collections.singletonList(
				Arrays.asList("Mirror shield", "V's shield"))),
			new WikiRequiredItemRule("Cockatrice", Collections.singletonList(
				Collections.singletonList("Mirror shield"))));

		String query = WikiRequiredItemResolver.buildBucketQuery(rules);

		assertEquals(1, occurrences(query, "Mirror shield"));
		assertTrue(query.contains("V\\'s shield"));
		assertTrue(query.contains("limit(500)"));
	}

	@Test
	public void resolvesAlternativeItemsIntoOneReminder()
	{
		WikiRequiredItemRule rule = new WikiRequiredItemRule("Gargoyle",
			Collections.singletonList(Arrays.asList("Rock hammer", "Rock thrownhammer")));
		String json = "{\"bucket\":["
			+ "{\"item_name\":\"Rock hammer\",\"item_id\":[\"4162\"]},"
			+ "{\"item_name\":\"Rock thrownhammer\",\"item_id\":[\"21754\"]}]}";

		Map<String, List<ReminderItem>> result = WikiRequiredItemResolver.resolve(
			Collections.singletonList(rule), new JsonParser().parse(json).getAsJsonObject());

		ReminderItem reminder = result.get("gargoyle").get(0);
		assertEquals("Rock hammer or Rock thrownhammer", reminder.getName());
		assertTrue(contains(reminder.getItemIds(), 4162));
		assertTrue(contains(reminder.getItemIds(), 21754));
	}

	@Test
	public void resolvesLitBullseyeLanternMissingFromBucketByItsGameId()
	{
		WikiRequiredItemRule rule = new WikiRequiredItemRule("Cave horror", Arrays.asList(
			Collections.singletonList("Witchwood icon"),
			Collections.singletonList("Bullseye lantern (lit)")));
		String json = "{\"bucket\":["
			+ "{\"item_name\":\"Witchwood icon\",\"item_id\":[\"8923\"]}]}";

		Map<String, List<ReminderItem>> result = WikiRequiredItemResolver.resolve(
			Collections.singletonList(rule), new JsonParser().parse(json).getAsJsonObject());

		List<ReminderItem> reminders = result.get("cave horror");
		assertEquals(2, reminders.size());
		assertEquals("Bullseye lantern (lit)", reminders.get(1).getName());
		assertTrue(contains(reminders.get(1).getItemIds(), ItemID.BULLSEYE_LANTERN_LIT));
		assertFalse(contains(reminders.get(1).getItemIds(), ItemID.BULLSEYE_LANTERN_UNLIT));
	}

	@Test
	public void rejectsCompoundRuleWhenAnyGroupCannotBeResolved()
	{
		WikiRequiredItemRule rule = new WikiRequiredItemRule("Warped Terrorbird", Arrays.asList(
			Collections.singletonList("Crystal chime"),
			Arrays.asList("Earmuffs", "Slayer helmet")));
		String json = "{\"bucket\":[{\"item_name\":\"Crystal chime\",\"item_id\":[\"28577\"]}]}";

		Map<String, List<ReminderItem>> result = WikiRequiredItemResolver.resolve(
			Collections.singletonList(rule), new JsonParser().parse(json).getAsJsonObject());

		assertFalse(result.containsKey("warped terrorbird"));
	}

	private static int occurrences(String value, String needle)
	{
		return (value.length() - value.replace(needle, "").length()) / needle.length();
	}

	private static boolean contains(int[] values, int expected)
	{
		return Arrays.stream(values).anyMatch(value -> value == expected);
	}
}

package com.slayeritemreminders;

import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class WikiTaskVariantParserTest
{
	@Test
	public void parsesAndDeduplicatesMonsterVariantRows()
	{
		String wikiText = "Introduction\n"
			+ "==Monster variants==\n"
			+ "{| class=\"wikitable\"\n!Monster\n!Level\n"
			+ "|-\n|[[Greater Demon]]\n|92\n"
			+ "|-\n|[[Greater Demon]]\n|100\n"
			+ "|-\n|[[Tormented Demon|Tormented demon]]\n|450\n"
			+ "|}\n==Locations==\n|[[Not a monster]]\n";

		List<TaskVariant> variants = WikiTaskVariantParser.parse(wikiText);

		assertEquals(2, variants.size());
		assertEquals("Greater Demon", variants.get(0).getWikiPage());
		assertEquals("Tormented demon", variants.get(1).getName());
		assertEquals("Tormented Demon", variants.get(1).getWikiPage());
	}

	@Test
	public void parsesEveryMonsterLinkedInOneCell()
	{
		String wikiText = "==Monster variants==\n"
			+ "{| class=\"wikitable\"\n!Monster\n!Location\n"
			+ "|-\n|[[Dagannoth Prime]]\n[[Dagannoth Rex]]\n\n[[Dagannoth Supreme]]\n"
			+ "|[[Waterbirth Island Dungeon]]\n|}\n";

		List<TaskVariant> variants = WikiTaskVariantParser.parse(wikiText);

		assertEquals(3, variants.size());
		assertEquals("Dagannoth Prime", variants.get(0).getWikiPage());
		assertEquals("Dagannoth Rex", variants.get(1).getWikiPage());
		assertEquals("Dagannoth Supreme", variants.get(2).getWikiPage());
	}

	@Test
	public void parsesCaveKrakenBossVariant()
	{
		String wikiText = "==Monster Variants==\n"
			+ "{| class=\"wikitable\"\n!Monster\n!Location\n"
			+ "|-\n|[[Cave kraken]]\n|[[Kraken Cove]]\n"
			+ "|-\n|[[Kraken]]\n|[[Kraken Cove]]\n|}\n";

		List<TaskVariant> variants = WikiTaskVariantParser.parse(wikiText);

		assertEquals(2, variants.size());
		assertEquals("Kraken", variants.get(1).getWikiPage());
	}

	@Test
	public void generatesPluralFallbackForCaveKrakenTaskPage()
	{
		assertEquals("Cave kraken", WikiTaskVariantClient.taskPageCandidates("Cave kraken").get(0));
		assertEquals("Cave krakens", WikiTaskVariantClient.taskPageCandidates("Cave kraken").get(1));
	}

	@Test
	public void generatesSingularFallbackForPluralTaskPage()
	{
		assertEquals("Greater demon", WikiTaskVariantClient.taskPageCandidates("Greater demons").get(1));
	}

	@Test
	public void usesCanonicalBlackDemonsTaskPageForEitherTaskName()
	{
		assertEquals("Black demons", WikiTaskVariantClient.taskPageCandidates("Black demons").get(0));
		assertEquals("Black demons", WikiTaskVariantClient.taskPageCandidates("Black demon").get(0));
	}

	@Test
	public void returnsEmptyListWithoutVariantSection()
	{
		assertTrue(WikiTaskVariantParser.parse("==Locations==\nNothing here").isEmpty());
	}
}

package com.slayeritemreminders;

