package com.slayeritemreminders;

import java.io.IOException;
import java.io.StringReader;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import javax.swing.text.MutableAttributeSet;
import javax.swing.text.html.HTML;
import javax.swing.text.html.HTMLEditorKit;
import javax.swing.text.html.parser.ParserDelegator;

final class DropTableParser
{
	private static final int RECOMMENDATION_THRESHOLD = 4;

	private DropTableParser()
	{
	}

	static Set<RecommendedItem> parse(String html) throws IOException
	{
		DropTableCallback callback = new DropTableCallback();
		new ParserDelegator().parse(new StringReader(html), callback, true);

		EnumSet<RecommendedItem> recommendations = EnumSet.noneOf(RecommendedItem.class);
		if (callback.herbs.size() >= RECOMMENDATION_THRESHOLD)
		{
			recommendations.add(RecommendedItem.HERB_SACK);
		}
		if (callback.seeds.size() >= RECOMMENDATION_THRESHOLD)
		{
			recommendations.add(RecommendedItem.SEED_BOX);
		}
		return recommendations;
	}

	private static boolean isDropsHeading(Object id)
	{
		if (id == null)
		{
			return false;
		}
		String heading = id.toString().toLowerCase(Locale.ENGLISH);
		return heading.equals("drops") || heading.endsWith("_drops");
	}

	private static boolean isHerb(String item)
	{
		return item.startsWith("grimy ");
	}

	private static boolean isSeed(String item)
	{
		// TODO: Consider deriving seed box compatibility from https://oldschool.runescape.wiki/w/Seeds.
		return (item.endsWith(" seed") && !item.contains("crystal"))
			|| item.equals("acorn")
			|| item.endsWith(" spore");
	}

	private static final class DropTableCallback extends HTMLEditorKit.ParserCallback
	{
		private final Set<String> herbs = new HashSet<>();
		private final Set<String> seeds = new HashSet<>();
		private final Set<String> rowItems = new HashSet<>();
		private final StringBuilder rowText = new StringBuilder();
		private boolean inDrops;
		private boolean inRow;

		@Override
		public void handleStartTag(HTML.Tag tag, MutableAttributeSet attributes, int position)
		{
			if (tag == HTML.Tag.H2)
			{
				inDrops = isDropsHeading(attributes.getAttribute(HTML.Attribute.ID));
			}
			else if (inDrops && tag == HTML.Tag.TR)
			{
				inRow = true;
				rowItems.clear();
				rowText.setLength(0);
			}
			else if (inDrops && inRow && tag == HTML.Tag.A)
			{
				Object title = attributes.getAttribute(HTML.Attribute.TITLE);
				if (title != null)
				{
					rowItems.add(title.toString().toLowerCase(Locale.ENGLISH));
				}
			}
		}

		@Override
		public void handleText(char[] data, int position)
		{
			if (inDrops && inRow)
			{
				rowText.append(data);
			}
		}

		@Override
		public void handleEndTag(HTML.Tag tag, int position)
		{
			if (tag == HTML.Tag.TR && inRow)
			{
				if (!rowText.toString().toLowerCase(Locale.ENGLISH).contains("noted"))
				{
					rowItems.stream().filter(DropTableParser::isHerb).forEach(herbs::add);
					rowItems.stream().filter(DropTableParser::isSeed).forEach(seeds::add);
				}
				inRow = false;
			}
		}
	}
}

package com.slayeritemreminders;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;

final class WikiRequiredItemResolver
{
	private WikiRequiredItemResolver()
	{
	}

	static String buildBucketQuery(List<WikiRequiredItemRule> rules)
	{
		Set<String> names = new LinkedHashSet<>();
		for (WikiRequiredItemRule rule : rules)
		{
			for (List<String> group : rule.getRequirementGroups())
			{
				names.addAll(group);
			}
		}
		String conditions = names.stream()
			.map(name -> "{'item_name','" + escapeLua(name) + "'}")
			.collect(Collectors.joining(","));
		return "bucket('infobox_item').select('item_name','item_id')"
			+ ".where(bucket.Or(" + conditions + ")).limit(500).run()";
	}

	static Map<String, List<ReminderItem>> resolve(List<WikiRequiredItemRule> rules, JsonObject response)
	{
		Map<String, Set<Integer>> idsByName = parseItemIds(response);
		Map<String, List<ReminderItem>> result = new LinkedHashMap<>();
		for (WikiRequiredItemRule rule : rules)
		{
			List<ReminderItem> requirements = new ArrayList<>();
			boolean complete = true;
			for (List<String> group : rule.getRequirementGroups())
			{
				Set<Integer> ids = new LinkedHashSet<>();
				List<String> resolvedNames = new ArrayList<>();
				for (String name : group)
				{
					Set<Integer> knownIds = knownItemIds(name);
					if (!knownIds.isEmpty())
					{
						resolvedNames.add(name);
						ids.addAll(knownIds);
						continue;
					}

					Set<Integer> itemIds = idsByName.get(key(name));
					if (itemIds != null && !itemIds.isEmpty())
					{
						resolvedNames.add(name);
						for (int itemId : itemIds)
						{
							Collection<Integer> variations = ItemVariationMapping.getVariations(
								ItemVariationMapping.map(itemId));
							ids.addAll(variations);
						}
					}
				}
				if (ids.isEmpty())
				{
					complete = false;
					break;
				}
				int[] itemIds = ids.stream().mapToInt(Integer::intValue).toArray();
				requirements.add(new ReminderItem(
					String.join(" or ", resolvedNames), itemIds));
			}
			if (complete && !requirements.isEmpty())
			{
				result.put(key(rule.getMonster()),
					Collections.unmodifiableList(requirements));
			}
		}
		return Collections.unmodifiableMap(result);
	}

	private static Map<String, Set<Integer>> parseItemIds(JsonObject response)
	{
		Map<String, Set<Integer>> idsByName = new LinkedHashMap<>();
		JsonArray rows = response.getAsJsonArray("bucket");
		if (rows == null)
		{
			return idsByName;
		}
		for (JsonElement element : rows)
		{
			JsonObject row = element.getAsJsonObject();
			if (!row.has("item_name") || !row.has("item_id"))
			{
				continue;
			}
			Set<Integer> ids = idsByName.computeIfAbsent(
				key(row.get("item_name").getAsString()), ignored -> new LinkedHashSet<>());
			JsonElement idValue = row.get("item_id");
			if (idValue.isJsonArray())
			{
				for (JsonElement id : idValue.getAsJsonArray())
				{
					addId(ids, id);
				}
			}
			else
			{
				addId(ids, idValue);
			}
		}
		return idsByName;
	}

	private static Set<Integer> knownItemIds(String name)
	{
		if ("bullseye lantern (lit)".equals(key(name)))
		{
			Set<Integer> ids = new LinkedHashSet<>();
			ids.add(ItemID.BULLSEYE_LANTERN_LIT);
			ids.add(ItemID.BULLSEYE_LANTERN_LIT_LUNAR_QUEST);
			return ids;
		}
		return Collections.emptySet();
	}

	private static void addId(Set<Integer> ids, JsonElement value)
	{
		try
		{
			ids.add(Integer.parseInt(value.getAsString()));
		}
		catch (NumberFormatException ignored)
		{
			// Ignore malformed external data rather than creating an invalid item requirement.
		}
	}

	private static String escapeLua(String value)
	{
		return value.replace("\\", "\\\\").replace("'", "\\'");
	}

	private static String key(String value)
	{
		return value.toLowerCase(Locale.ENGLISH);
	}
}

package com.slayeritemreminders;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

@Getter
enum RecommendedItem
{
	HERB_SACK(new ReminderItem("Herb sack",
		ItemID.SLAYER_HERB_SACK,
		ItemID.SLAYER_HERB_SACK_OPEN,
		ItemID.SLAYER_HERB_SACK_SILK,
		ItemID.SLAYER_HERB_SACK_SILK_OPEN)),
	SEED_BOX(new ReminderItem("Seed box",
		ItemID.SEED_BOX,
		ItemID.SEED_BOX_OPEN));

	private final ReminderItem reminderItem;

	RecommendedItem(ReminderItem reminderItem)
	{
		this.reminderItem = reminderItem;
	}
}

package com.slayeritemreminders;

import java.util.Collections;
import java.util.List;
import lombok.Getter;

@Getter
final class TaskVariant
{
	private final String name;
	private final String wikiPage;
	private final List<ReminderItem> requiredItems;

	TaskVariant(String name, String wikiPage, List<ReminderItem> requiredItems)
	{
		this.name = name;
		this.wikiPage = wikiPage;
		this.requiredItems = Collections.unmodifiableList(requiredItems);
	}

	TaskVariant(String name, String wikiPage)
	{
		this(name, wikiPage, Collections.emptyList());
	}
}

